update lessons set objective_ar='أحلّل قصيدة «النهر المتجمد» لميخائيل نعيمة، وأفسّر صورها الفنية (التشخيص والاستعارة)، وأقارن بين حالي النهر في الشتاء والربيع، وأستنتج موقف الشاعر بين اليأس والأمل.' where code='AR-Y8-N-T2-L09';
update success_criteria set statement_ar='أفسّر مفردات القصيدة وأحدّد فكرة كل مقطع.' where sort_order=1 and lesson_id=(select id from lessons where code='AR-Y8-N-T2-L09');
update success_criteria set statement_ar='أحلّل صور التشخيص والاستعارة وأبيّن أثرها في نقل الحالة الشعورية.' where sort_order=2 and lesson_id=(select id from lessons where code='AR-Y8-N-T2-L09');
update success_criteria set statement_ar='أقارن بين حالي النهر وحال قلب الشاعر، وأبدي رأيي في نظرته إلى الحياة بدليل.' where sort_order=3 and lesson_id=(select id from lessons where code='AR-Y8-N-T2-L09');
update lesson_summaries set content=content||'{"emoji": "🧊", "hook": "نهر كان يغنّي بين الحدائق… ثم سكت تحت الجليد. بماذا يشعر؟ ومن يشبهه؟", "idea": "قصيدة لميخائيل نعيمة يخاطب فيها نهرًا تجمّد في الشتاء، ويبشّره بعودة الربيع، ثم يشكو قلبه الذي تجمّد ولن يعود.", "learn": [["📖", "أقرأ القصيدة في كتابي ص 104–105."], ["🧊", "المقطع الأول: النهر مكبّل بالجليد، والطبيعة حوله حزينة."], ["🌸", "المقطع الثاني: سيعود الربيع فيفكّ النهر من عقاله."], ["💔", "المقطع الثالث: قلب الشاعر تجمّد ولن ينشط مثل النهر."], ["🎨", "التشخيص: منح الجماد صفات الإنسان، مثل «هرمتَ وخار عزمك»."]], "quiz": [["شبّه الشاعر قلبه بالنهر المتجمّد.", true], ["ينتهي النص بأن قلب الشاعر سيعود مع الربيع.", false]], "words": [["نَضَبَتْ", "غارت وجفّت"], ["خارَ", "ضعف"], ["كَبَّلَتْكَ", "قيّدتك"], ["الصَّقيع", "البرد الشديد والجليد"]], "think": "هل الحياة تتوقّف عند المصائب؟ وماذا أقول لمن فقد الأمل؟"}'::jsonb where lesson_id=(select id from lessons where code='AR-Y8-N-T2-L09');